CREATE DATABASE IF NOT EXISTS hoop_house CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE hoop_house;
CREATE TABLE IF NOT EXISTS users (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, role ENUM('customer','staff') NOT NULL DEFAULT 'customer');
CREATE TABLE IF NOT EXISTS gym_sessions (id INT AUTO_INCREMENT PRIMARY KEY, title VARCHAR(120) NOT NULL, starts_at DATETIME NOT NULL, capacity INT NOT NULL, created_by INT NULL, FOREIGN KEY(created_by) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS registrations (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, session_id INT NOT NULL, status ENUM('registered','cancelled') NOT NULL DEFAULT 'registered', UNIQUE KEY unique_registration(user_id,session_id), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(session_id) REFERENCES gym_sessions(id));
CREATE TABLE IF NOT EXISTS teams (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL UNIQUE, captain_id INT NOT NULL, max_players INT NOT NULL DEFAULT 8, description VARCHAR(255) DEFAULT '', recruiting TINYINT NOT NULL DEFAULT 1, FOREIGN KEY(captain_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS team_memberships (id INT AUTO_INCREMENT PRIMARY KEY, team_id INT NOT NULL, user_id INT NOT NULL, UNIQUE KEY unique_member(team_id,user_id), FOREIGN KEY(team_id) REFERENCES teams(id), FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS team_requests (id INT AUTO_INCREMENT PRIMARY KEY, team_id INT NOT NULL, user_id INT NOT NULL, status ENUM('pending','approved','declined') NOT NULL DEFAULT 'pending', UNIQUE KEY unique_request(team_id,user_id), FOREIGN KEY(team_id) REFERENCES teams(id), FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS leagues (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, season VARCHAR(80) NOT NULL);
CREATE TABLE IF NOT EXISTS league_teams (id INT AUTO_INCREMENT PRIMARY KEY, league_id INT NOT NULL, team_id INT NOT NULL, UNIQUE KEY unique_league_team(league_id,team_id), FOREIGN KEY(league_id) REFERENCES leagues(id), FOREIGN KEY(team_id) REFERENCES teams(id));
CREATE TABLE IF NOT EXISTS equipment (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, total_quantity INT NOT NULL, available_quantity INT NOT NULL, damaged_quantity INT NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS equipment_checkouts (id INT AUTO_INCREMENT PRIMARY KEY, equipment_id INT NOT NULL, user_id INT NOT NULL, staff_id INT NULL, quantity INT NOT NULL DEFAULT 1, status ENUM('requested','checked_out','returned','cancelled') NOT NULL DEFAULT 'requested', requested_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(equipment_id) REFERENCES equipment(id), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(staff_id) REFERENCES users(id));
INSERT INTO equipment(name,total_quantity,available_quantity) SELECT 'Basketball',10,10 WHERE NOT EXISTS (SELECT 1 FROM equipment WHERE name='Basketball');
INSERT INTO equipment(name,total_quantity,available_quantity) SELECT 'Training Cones',20,20 WHERE NOT EXISTS (SELECT 1 FROM equipment WHERE name='Training Cones');
